from decimal import Decimal

def parse_inr(text):
    if not text.startswith('₹'):
        raise InvoiceError('INVALID_INR_FORMAT')
    text = text[1:].replace(',', '')
    try:
        return int(Decimal(text) * 100)
    except ValueError:
        raise InvoiceError('INVALID_INR_FORMAT')

